{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A surface or arrangement providing a place for refreshments for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "coffee table",
          "side table",
          "desk",
          "tray"
        ],
        "required_properties": [
          "suitable for holding cups/plates",
          "near seating area"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "remote control",
          "media controller"
        ],
        "required_properties": [
          "capable of controlling TV"
        ]
      },
      {
        "id": "accessible_location",
        "entity_kind": "REGION",
        "function": "A spot reachable by both seated people.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "coffee table surface",
          "center of floor",
          "side table surface"
        ],
        "required_properties": [
          "within reach of both chairs"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_proximity",
        "relation": "refreshment_setting is situated near accessible_location",
        "participant_roles": [
          "refreshment_setting",
          "accessible_location"
        ]
      ,
        "required": true
      },
      {
        "id": "control_placement",
        "relation": "entertainment_control is situated at accessible_location",
        "participant_roles": [
          "entertainment_control",
          "accessible_location"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "establish_refreshment_setting",
        "operation": "Provide each person with their own refreshment setting nearby",
        "participant_roles": [
          "refreshment_setting",
          "accessible_location"
        ],
        "operation_count": 2
      },
      {
        "id": "position_entertainment_control",
        "operation": "Place the entertainment control where it is accessible to both people",
        "participant_roles": [
          "entertainment_control",
          "accessible_location"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "coffee_table",
          "visual_description": "Central low table with a cup on it."
        },
        {
          "label": "side_table_left",
          "visual_description": "Small wooden table next to left chair with a plate on it."
        },
        {
          "label": "side_table_right",
          "visual_description": "Small wooden table next to right chair."
        },
        {
          "label": "desk",
          "visual_description": "Large wooden desk in foreground with plate, cup, and remote."
        }
      ],
      "entertainment_control": [
        {
          "label": "remote_on_desk",
          "visual_description": "Black rectangular object on the desk."
        }
      ],
      "accessible_location": [
        {
          "label": "coffee_table_surface",
          "visual_description": "Top of the central coffee table."
        },
        {
          "label": "side_tables",
          "visual_description": "Surfaces of the small side tables."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_storage",
        "label": "Desk lower compartment",
        "visual_description": "Dark area under the desk surface, possibly containing storage.",
        "reason": "Could contain additional remotes or refreshment supplies."
      },
      {
        "id": "side_table_shelves",
        "label": "Side table shelves",
        "visual_description": "Open shelving under side tables.",
        "reason": "Could contain hidden refreshments or controls."
      },
      {
        "id": "bench_under_tv",
        "label": "Bench under television",
        "visual_description": "Long wooden bench beneath the wall-mounted TV.",
        "reason": "Could contain media equipment or accessories."
      }
    ],
    "inspection_order": [
      "desk_storage",
      "side_table_shelves",
      "bench_under_tv"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
